CREATE TABLE Users (
    UserID INT PRIMARY KEY,
    PhoneNumber VARCHAR(20)  -- Note: VARCHAR type
);
CREATE INDEX IX_PhoneNumber ON Users(PhoneNumber);

-- Application Code
DECLARE @Phone NVARCHAR(20) = N'0912345678'; -- Note: NVARCHAR type
SELECT UserID FROM Users WHERE PhoneNumber = @Phone;

