DECLARE cur CURSOR FOR SELECT ProductID, NewPrice FROM #PriceUpdates;
OPEN cur;
FETCH NEXT FROM cur INTO @Pid, @Price;
WHILE @@FETCH_STATUS = 0
BEGIN
    UPDATE Products SET Price = @Price WHERE ID = @Pid;
    FETCH NEXT FROM cur INTO @Pid, @Price;
END
CLOSE cur;
DEALLOCATE cur;
